//! Counts the MIR and generated bytes of a saved audit probe; never runs it.
use badger_mir::{Callee, Const, FuncId, Operand, Rvalue, Stmt, Term};
use std::collections::{BTreeSet, HashMap};

fn operands(rv: &Rvalue) -> Vec<&Operand> {
    match rv {
        Rvalue::Use(a) | Rvalue::Not(a) | Rvalue::ToWord(a) | Rvalue::Tag(a) => vec![a],
        Rvalue::Neg { a, .. }
        | Rvalue::Convert { a, .. }
        | Rvalue::Fits { a, .. }
        | Rvalue::FromWord { a, .. } => vec![a],
        Rvalue::Bin { a, b, .. } | Rvalue::Cmp { a, b, .. } | Rvalue::Overflows { a, b, .. } => vec![a, b],
        Rvalue::Load { base, .. } => vec![base],
        Rvalue::Call { callee, args, .. } => {
            let mut out: Vec<_> = args.iter().collect();
            if let Callee::Closure(c) = callee {
                out.push(c);
            }
            out
        }
        Rvalue::Concat(xs) => xs.iter().collect(),
        _ => vec![],
    }
}

fn main() {
    let path = std::env::args().nth(1).expect("saved MIR path");
    let (program, _) = badger_mir::serial::decode(&std::fs::read(path).unwrap()).unwrap();
    let closures: HashMap<u64, FuncId> = program.static_closures.iter().copied().collect();
    let mut reachable = BTreeSet::new();
    let mut todo: Vec<FuncId> = program
        .entry
        .into_iter()
        .chain(program.error_report)
        .chain(program.display_hooks.iter().map(|(_, f)| *f))
        .chain(program.static_closures.iter().map(|(_, f)| *f))
        .chain(program.tests.iter().map(|(_, f)| *f))
        .collect();
    while let Some(id) = todo.pop() {
        if !reachable.insert(id.index()) {
            continue;
        }
        let operand_target = |op: &Operand| match op {
            Operand::Const(Const::Addr(a)) => closures.get(a).copied(),
            _ => None,
        };
        for b in &program.funcs[id].blocks {
            for stmt in &b.stmts {
                match stmt {
                    Stmt::Assign(_, rv) => {
                        match rv {
                            Rvalue::FuncAddr(f)
                            | Rvalue::AdapterAddr(f)
                            | Rvalue::Call { callee: Callee::Direct(f), .. } => todo.push(*f),
                            _ => {}
                        }
                        todo.extend(operands(rv).into_iter().filter_map(operand_target));
                    }
                    Stmt::Store { base, value, .. } => {
                        todo.extend([base, value].into_iter().filter_map(operand_target))
                    }
                    Stmt::GlobalStore { value, .. } => todo.extend(operand_target(value)),
                    _ => {}
                }
            }
            if let Some(Term::Return(op) | Term::Branch(op, ..) | Term::Switch(op, ..)) = &b.term {
                todo.extend(operand_target(op));
            }
        }
    }
    println!(
        "functions={} reachable_from_entries_hooks_all_static_closures_and_address_references={}",
        program.funcs.len(),
        reachable.len()
    );
    let compiled = badger_codegen::compile(&program, true).unwrap();
    let mut total = 0;
    let mut unreferenced = 0;
    for (id, f) in program.funcs.iter_enumerated() {
        let roots = badger_mir::roots::rooted_locals(f);
        let null_roots = roots
            .iter()
            .filter(|local| {
                let defs: Vec<_> = f
                    .blocks
                    .iter()
                    .flat_map(|b| &b.stmts)
                    .filter_map(|s| match s {
                        Stmt::Assign(dst, rv) if dst == *local => Some(rv),
                        _ => None,
                    })
                    .collect();
                !f.params.contains(local)
                    && **local != f.env
                    && !defs.is_empty()
                    && defs.iter().all(|rv| {
                        matches!(
                            rv,
                            Rvalue::Use(Operand::Const(
                                Const::Addr(0) | Const::Int(0, badger_mir::Repr::Ptr)
                            ))
                        )
                    })
            })
            .count();
        let allocs = f
            .blocks
            .iter()
            .flat_map(|b| &b.stmts)
            .filter(|s| matches!(s, Stmt::Assign(_, Rvalue::Alloc { .. })))
            .count();
        let closures = f
            .blocks
            .iter()
            .flat_map(|b| &b.stmts)
            .filter(|s| matches!(s, Stmt::Assign(_, Rvalue::Call { callee: Callee::Closure(_), .. })))
            .count();
        let bytes = compiled.code.iter().find(|(_, _, n)| *n == f.name).map_or(0, |(_, b, _)| *b);
        total += bytes;
        if !reachable.contains(&id.index()) {
            unreferenced += bytes;
        }
        println!(
            "function={} reachable={} locals={} blocks={} roots={} always_null_roots={} alloc_sites={} closure_calls={} code_bytes={bytes}",
            f.name,
            reachable.contains(&id.index()),
            f.locals.len(),
            f.blocks.len(),
            roots.len(),
            null_roots,
            allocs,
            closures
        );
    }
    println!("function_code_bytes={total} unreferenced_function_code_bytes={unreferenced}");
}
